const rows = $input.all().map(i => i.json);
const swiggyN = rows[0]?.swiggy_n ?? 0;
const zomatoN = rows[0]?.zomato_n ?? 0;

const color = v => v === 'Swiggy worse' ? '#c0392b' : v === 'Swiggy better' ? '#27ae60' : '#555';

const tr = rows.map(r => `<tr>
  <td>${r.label}</td>
  <td align="center">${r.swiggy_per_1k ?? '-'}</td>
  <td align="center">${r.zomato_per_1k ?? '-'}</td>
  <td align="center">${r.gap ?? '-'}</td>
  <td style="color:${color(r.verdict)};font-weight:bold">${r.verdict}</td></tr>`).join('');

return [{ json: {
  subject: `Swiggy vs Zomato: customer pain report (${new Date().toDateString()})`,
  html: `<h2>Top complaints, last 7 days</h2>
    <p><b>Based on ${swiggyN} Swiggy and ${zomatoN} Zomato food reviews.</b><br>
    Mentions per 1,000 food reviews. Gap = Swiggy ÷ Zomato. Only issues with 3+ mentions.</p>
    <table border="1" cellpadding="6" style="border-collapse:collapse;font-family:Arial">
    <tr style="background:#f2f2f2"><th>Issue</th><th>Swiggy</th><th>Zomato</th><th>Gap</th><th>Verdict</th></tr>
    ${tr}</table>
    <p style="color:#888;font-size:12px">Small samples: a gap based on only a few reviews per brand is directional, not conclusive.</p>`,
}}];
